-- PostgreSQL CREATE TRIGGER defaults to FOR EACH STATEMENT. The integrity
-- functions in 0010 consume OLD/NEW row records, so they must be row-level.
-- This migration repairs the existing trigger definitions without rewriting
-- the historical 0010 migration.

DROP TRIGGER IF EXISTS attendance_coordinates_insert_guard ON public.attendance_records;
DROP TRIGGER IF EXISTS attendance_coordinates_update_guard ON public.attendance_records;
DROP TRIGGER IF EXISTS attendance_clock_order_guard ON public.attendance_records;
DROP TRIGGER IF EXISTS attendance_clock_order_insert_guard ON public.attendance_records;
DROP TRIGGER IF EXISTS leave_request_transition_guard ON public.leave_requests;
DROP TRIGGER IF EXISTS audit_logs_no_update ON public.audit_logs;
DROP TRIGGER IF EXISTS audit_logs_no_delete ON public.audit_logs;
DROP TRIGGER IF EXISTS platform_audit_logs_no_update ON public.platform_audit_logs;
DROP TRIGGER IF EXISTS platform_audit_logs_no_delete ON public.platform_audit_logs;
DROP TRIGGER IF EXISTS application_history_immutable_update ON public.application_history;
DROP TRIGGER IF EXISTS application_history_immutable_delete ON public.application_history;
DROP TRIGGER IF EXISTS interview_decisions_immutable_update ON public.interview_decisions;
DROP TRIGGER IF EXISTS interview_decisions_immutable_delete ON public.interview_decisions;
DROP TRIGGER IF EXISTS interview_feedback_immutable_update ON public.interview_feedback;
DROP TRIGGER IF EXISTS interview_feedback_immutable_delete ON public.interview_feedback;
DROP TRIGGER IF EXISTS interview_feedback_corrections_immutable_update ON public.interview_feedback_corrections;
DROP TRIGGER IF EXISTS interview_feedback_corrections_immutable_delete ON public.interview_feedback_corrections;
DROP TRIGGER IF EXISTS candidate_activities_immutable_update ON public.candidate_activities;
DROP TRIGGER IF EXISTS candidate_activities_immutable_delete ON public.candidate_activities;
DROP TRIGGER IF EXISTS candidate_documents_application_candidate_guard_insert ON public.candidate_documents;
DROP TRIGGER IF EXISTS candidate_documents_application_candidate_guard_update ON public.candidate_documents;
DROP TRIGGER IF EXISTS candidate_documents_immutable_identity ON public.candidate_documents;
DROP TRIGGER IF EXISTS candidate_documents_available_requires_clean_insert ON public.candidate_documents;
DROP TRIGGER IF EXISTS candidate_documents_available_requires_clean_update ON public.candidate_documents;
DROP TRIGGER IF EXISTS job_publications_immutable_identity ON public.job_publications;
DROP TRIGGER IF EXISTS job_publications_publish_guard ON public.job_publications;
DROP TRIGGER IF EXISTS offers_application_tenant_guard_insert ON public.offers;
DROP TRIGGER IF EXISTS offers_application_tenant_guard_update ON public.offers;
DROP TRIGGER IF EXISTS offers_no_delete ON public.offers;
DROP TRIGGER IF EXISTS offers_status_guard ON public.offers;
DROP TRIGGER IF EXISTS offers_identity_immutable ON public.offers;
DROP TRIGGER IF EXISTS offers_approved_terms_immutable ON public.offers;
DROP TRIGGER IF EXISTS offers_approved_metadata_guard ON public.offers;
DROP TRIGGER IF EXISTS offer_history_immutable_update ON public.offer_history;
DROP TRIGGER IF EXISTS offer_history_immutable_delete ON public.offer_history;
DROP TRIGGER IF EXISTS offer_response_rate_limit_nonnegative ON public.offer_response_rate_limits;
DROP TRIGGER IF EXISTS candidate_documents_offer_guard_insert ON public.candidate_documents;
DROP TRIGGER IF EXISTS candidate_documents_offer_guard_update ON public.candidate_documents;

CREATE TRIGGER attendance_coordinates_insert_guard BEFORE INSERT ON public.attendance_records FOR EACH ROW EXECUTE FUNCTION syj_attendance_guard();
CREATE TRIGGER attendance_coordinates_update_guard BEFORE UPDATE OF clock_in_lat,clock_in_lng,clock_out_lat,clock_out_lng ON public.attendance_records FOR EACH ROW EXECUTE FUNCTION syj_attendance_guard();
CREATE TRIGGER attendance_clock_order_guard BEFORE UPDATE OF clock_in_at,clock_out_at ON public.attendance_records FOR EACH ROW EXECUTE FUNCTION syj_attendance_guard();
CREATE TRIGGER attendance_clock_order_insert_guard BEFORE INSERT ON public.attendance_records FOR EACH ROW EXECUTE FUNCTION syj_attendance_guard();
CREATE TRIGGER leave_request_transition_guard BEFORE UPDATE OF status ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION syj_leave_request_transition_guard();
CREATE TRIGGER audit_logs_no_update BEFORE UPDATE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Audit logs are immutable');
CREATE TRIGGER audit_logs_no_delete BEFORE DELETE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Audit logs are immutable');
CREATE TRIGGER platform_audit_logs_no_update BEFORE UPDATE ON public.platform_audit_logs FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Platform audit logs are immutable');
CREATE TRIGGER platform_audit_logs_no_delete BEFORE DELETE ON public.platform_audit_logs FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Platform audit logs are immutable');
CREATE TRIGGER application_history_immutable_update BEFORE UPDATE ON public.application_history FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Application history is immutable.');
CREATE TRIGGER application_history_immutable_delete BEFORE DELETE ON public.application_history FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Application history is immutable.');
CREATE TRIGGER interview_decisions_immutable_update BEFORE UPDATE ON public.interview_decisions FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Interview decisions are immutable.');
CREATE TRIGGER interview_decisions_immutable_delete BEFORE DELETE ON public.interview_decisions FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Interview decisions are immutable.');
CREATE TRIGGER interview_feedback_immutable_update BEFORE UPDATE ON public.interview_feedback FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Interview feedback is immutable; use a correction record.');
CREATE TRIGGER interview_feedback_immutable_delete BEFORE DELETE ON public.interview_feedback FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Interview feedback is immutable.');
CREATE TRIGGER interview_feedback_corrections_immutable_update BEFORE UPDATE ON public.interview_feedback_corrections FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Feedback corrections are immutable.');
CREATE TRIGGER interview_feedback_corrections_immutable_delete BEFORE DELETE ON public.interview_feedback_corrections FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Feedback corrections are immutable.');
CREATE TRIGGER candidate_activities_immutable_update BEFORE UPDATE ON public.candidate_activities FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Candidate activities are immutable.');
CREATE TRIGGER candidate_activities_immutable_delete BEFORE DELETE ON public.candidate_activities FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Candidate activities are immutable.');
CREATE TRIGGER candidate_documents_application_candidate_guard_insert BEFORE INSERT ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_candidate_document_guard();
CREATE TRIGGER candidate_documents_application_candidate_guard_update BEFORE UPDATE OF organization_id,candidate_id,application_id ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_candidate_document_guard();
CREATE TRIGGER candidate_documents_immutable_identity BEFORE UPDATE OF organization_id,candidate_id,application_id,document_type,storage_key,checksum_sha256,uploaded_by,created_at ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Document identity is immutable.');
CREATE TRIGGER candidate_documents_available_requires_clean_insert BEFORE INSERT ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_candidate_document_guard();
CREATE TRIGGER candidate_documents_available_requires_clean_update BEFORE UPDATE OF lifecycle_status,scan_status ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_candidate_document_guard();
CREATE TRIGGER job_publications_immutable_identity BEFORE UPDATE OF organization_id,job_requisition_id,id,created_by,created_at ON public.job_publications FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Job publication identity is immutable.');
CREATE TRIGGER job_publications_publish_guard BEFORE UPDATE OF status ON public.job_publications FOR EACH ROW EXECUTE FUNCTION syj_job_publication_guard();
CREATE TRIGGER offers_application_tenant_guard_insert BEFORE INSERT ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_offer_application_guard();
CREATE TRIGGER offers_application_tenant_guard_update BEFORE UPDATE OF organization_id,application_id ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_offer_application_guard();
CREATE TRIGGER offers_no_delete BEFORE DELETE ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Offers cannot be hard-deleted.');
CREATE TRIGGER offers_status_guard BEFORE UPDATE OF status ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_offer_status_guard();
CREATE TRIGGER offers_identity_immutable BEFORE UPDATE OF organization_id,application_id,offer_reference,version,created_by,created_at,supersedes_offer_id ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Offer identity is immutable.');
CREATE TRIGGER offers_approved_terms_immutable BEFORE UPDATE OF currency,base_salary_minor,pay_frequency,variable_comp_minor,joining_bonus_minor,allowances_minor,other_comp_minor,benefits_summary,employment_terms,proposed_joining_date,expires_at ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_offer_terms_guard();
CREATE TRIGGER offers_approved_metadata_guard BEFORE UPDATE OF approved_by,approved_at,rejection_reason,sent_at,responded_at,response_reason,candidate_response_token_hash,candidate_response_token_expires_at,candidate_response_token_revoked_at,candidate_response_token_used_at ON public.offers FOR EACH ROW EXECUTE FUNCTION syj_offer_terminal_guard();
CREATE TRIGGER offer_history_immutable_update BEFORE UPDATE ON public.offer_history FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Offer history is immutable.');
CREATE TRIGGER offer_history_immutable_delete BEFORE DELETE ON public.offer_history FOR EACH ROW EXECUTE FUNCTION syj_immutable_row('Offer history is immutable.');
CREATE TRIGGER offer_response_rate_limit_nonnegative BEFORE UPDATE OF request_count ON public.offer_response_rate_limits FOR EACH ROW EXECUTE FUNCTION syj_offer_response_rate_guard();
CREATE TRIGGER candidate_documents_offer_guard_insert BEFORE INSERT ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_offer_document_guard();
CREATE TRIGGER candidate_documents_offer_guard_update BEFORE UPDATE OF organization_id,candidate_id,application_id,offer_id ON public.candidate_documents FOR EACH ROW EXECUTE FUNCTION syj_offer_document_guard();
